// ── Platform health check ────────────────────────────────────────────────
// Edit TARGETS to match the services you want watched. n8n runs on the
// `internal` + `proxy` Docker networks, so it reaches platform containers by
// their service NAME (no host ports needed). On-demand services that are
// intentionally stopped will report DOWN here — that is expected.
const TARGETS = [
  { name: 'Uptime Kuma', url: 'http://uptime-kuma:3001' },
  { name: 'Portainer',   url: 'http://portainer:9000' },
  // Examples — add your own (only checks pass while the service is running):
  // { name: 'Keycloak', url: 'http://keycloak:8080' },
  // { name: 'My app',   url: 'http://<service-name>:<port>/health' },
];

const TIMEOUT_MS = 10000;
const results = [];

for (const t of TARGETS) {
  const started = Date.now();
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: t.url,
      timeout: TIMEOUT_MS,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    const code = res.statusCode;
    const ok = code >= 200 && code < 400;
    results.push({
      name: t.name, url: t.url, healthy: ok, statusCode: code,
      ms: Date.now() - started, error: ok ? null : ('HTTP ' + code),
    });
  } catch (err) {
    results.push({
      name: t.name, url: t.url, healthy: false, statusCode: null,
      ms: Date.now() - started,
      error: (err && err.message) ? err.message : String(err),
    });
  }
}

const failures = results.filter(r => !r.healthy);
const summary = {
  checkedAt: new Date().toISOString(),
  total: results.length,
  healthy: results.length - failures.length,
  unhealthy: failures.length,
  hasFailures: failures.length > 0,
  results,
  failures,
};

// Always log the outcome so a plain `docker logs` / the n8n execution log is
// the zero-config 'alert' channel even before you wire a real notifier.
if (summary.hasFailures) {
  console.error('[platform-health] DOWN: ' + JSON.stringify(failures));
} else {
  console.log('[platform-health] all ' + summary.total + ' services healthy');
}

return [{ json: summary }];
